  var KWNEW = {"approach": "approach process method design think", "interest": "looking next grow team goals interested", "where": "where based location milan remote hybrid onsite", "projects": "projects work cases portfolio", "p_homizy": "homizy coliving compatibility", "h_research": "homizy research survey interview benchmark", "h_insights": "homizy insights insight findings", "h_solution": "homizy solution zymatch zymate archetypes matching", "p_lumen": "lumen agent tonidigrigio", "l_data": "lumen numbers data stats budget", "l_solution": "lumen solution agent workflow", "p_antianti": "antianti fashion app", "a_solution": "antianti solution kintsugi subscription repair", "p_perii": "perii alzheimer wandering caregiver", "pe_solution": "perii bracelet gps solution safe zone", "pe_research": "perii research interviews", "topic_me": "giacomo about him profile person", "experience": "experience work internship job sketchin biagetti career", "education": "study studied education degree master university school"};
